import path from 'node:path';

export function resolveRelative(root, value) {
    if (typeof root !== 'string' || typeof value !== 'string') {
        throw new Error('root and value must be strings');
    }
    // If value is absolute, throw
    if (path.isAbsolute(value)) {
        throw new Error(`Path escapes the workspace: ${value}`);
    }

    const resolved = path.resolve(root, value);
    const rel = path.relative(root, resolved);
    if (rel.startsWith('..') || path.isAbsolute(rel)) {
        throw new Error(`Path escapes the workspace: ${value}`);
    }
    return resolved;
}

import { test } from 'node:test';
import assert from 'node:assert';

import { resolveRelative } from '../src/lib.mjs';

const root = '/tmp/workspace';

function assertResolve(value, expected) {
    const result = resolveRelative(root, value);
    assert.strictEqual(result, expected);
}

function assertThrows(value, snippet) {
    assert.throws(
        () => resolveRelative(root, value),
        (err) => err instanceof Error && err.message.includes(snippet)
    );
}

test('resolves simple relative path', () => {
    assertResolve('foo/bar.txt', '/tmp/workspace/foo/bar.txt');
});

test('throws on absolute path', () => {
    assertThrows('/etc/passwd', 'escapes');
});

test('throws on ancestor traversal', () => {
    assertThrows('../../secret', 'escapes');
});

test('does not accept non-string', () => {
    // @ts-expect-error
    assert.throws(() => resolveRelative(root, 42), /error/i);
});
