export function paginate(items, page = 1, size = 20) {
  if (!Number.isInteger(page) || page < 1) throw new Error('Page must be a positive integer');
  if (!Number.isInteger(size) || size < 1 || size > 100) throw new Error('Page size must be between 1 and 100');
  const start = (page - 1) * size;
  return { items: items.slice(start, start + size), page, pages: Math.max(1, Math.ceil(items.length / size)), total: items.length };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { filterTasks } from '../src/query.mjs';

const tasks = [
  { id: 1, title: 'Buy milk', notes: 'Remember cheese', priority: 'low', status: 'open', due: '2026-11-05', tags: ['home'] },
  { id: 2, title: 'Meeting', notes: 'Project kickoff', priority: 'high', status: 'done', due: null, tags: ['work'] },
  { id: 3, title: 'Write report', notes: '', priority: 'normal', status: 'open', due: '2026-10-30', tags: ['work'] },
  { id: 4, title: 'Call friend', notes: 'BR', priority: 'high', status: 'open', due: '2026-11-02', tags: [] }
];

test('search matches title or notes (case-insensitive), whitespace-only ignored', () => {
  assert.deepEqual(filterTasks(tasks, { search: 'milk' }).map(t => t.id), [1]);
  assert.deepEqual(filterTasks(tasks, { search: 'project' }).map(t => t.id), [2]);
  assert.deepEqual(filterTasks(tasks, { search: '  ' }).map(t => t.id), [1,2,3,4]);
  assert.deepEqual(filterTasks(tasks, { search: 'BR' }).map(t => t.id), [4]);
});
